        body.putIfAbsent("status","沟通中");if(!PERSON_STATUSES.contains(str(body,"status")))throw ApiException.bad("应聘阶段不正确");if(applicationId!=null&&Set.of("面试安排","面试中","内部决策","面试").contains(str(body,"status"))&&Objects.requireNonNull(db.queryForObject("SELECT COUNT(*) FROM interview WHERE org_id=? AND person_id=? AND application_id=?",Integer.class,user.org(),personId,applicationId))==0)throw ApiException.bad("进入面试流程前必须先建立至少一条面试安排");if(str(body,"owner").isBlank())body.put("owner",basePerson(personId).get("owner"));long ownerId=employeeId(str(body,"owner"));validateDates(body);validateIntent(body);reason(body,before);boolean enteringOnboarding="已入职".equals(str(body,"status"))&&!"已入职".equals(str(before,"status"));if(enteringOnboarding)validateOnboarding(onboarding);
        String timestamp=now();body.put("updatedAt",timestamp);body.put("personId",personId);if(applicationId==null){body.put("createdAt",timestamp);body.put("createdBy",user.name());body.put("revision",1);applicationId=insertApplication(personId,ownerId,body);}else{long expected=version(input,"revision");body.put("revision",expected+1);if(updateApplication(applicationId,personId,expected,ownerId,body)==0)throw ApiException.conflict();}
