    private void syncEmploymentStatus(long personId,Map<String,Object> employment){String status=str(employment,"status");db.update("UPDATE person SET status=?,result='录用',reason=?,updated_at=?,revision=revision+1 WHERE id=? AND org_id=?","已离职".equals(status)?"已离职":status,str(employment,"reason"),now(),personId,user.org());}
    private void advanceApplication(long personId,Long applicationId,String status){if(applicationId==null)return;if(Set.of("面试安排","面试中","内部决策","面试").contains(status)&&Objects.requireNonNull(db.queryForObject("SELECT COUNT(*) FROM interview WHERE org_id=? AND person_id=? AND application_id=?",Integer.class,user.org(),personId,applicationId))==0)throw ApiException.bad("进入面试流程前必须先建立至少一条面试安排");String timestamp=now();db.update("UPDATE application SET status=?,updated_at=?,revision=revision+1 WHERE id=? AND person_id=? AND org_id=?",status,timestamp,applicationId,personId,user.org());Long newest=db.queryForObject("SELECT MAX(id) FROM application WHERE org_id=? AND person_id=?",Long.class,user.org(),personId);if(Objects.equals(newest,applicationId))db.update("UPDATE person SET status=?,updated_at=?,revision=revision+1 WHERE id=? AND org_id=?",status,timestamp,personId,user.org());}
    private void closeApplicationFromInterview(long personId,Long applicationId,Map<String,Object> interview){if(applicationId==null)return;String feedback=str(interview,"feedback"),reason=feedback.isBlank()?"面试结论为不推荐":"面试不推荐："+feedback,timestamp=now();db.update("UPDATE application SET status='公司淘汰',company_intent='放弃',reason=?,updated_at=?,revision=revision+1 WHERE id=? AND person_id=? AND org_id=?",reason,timestamp,applicationId,personId,user.org());Long newest=db.queryForObject("SELECT MAX(id) FROM application WHERE org_id=? AND person_id=?",Long.class,user.org(),personId);if(Objects.equals(newest,applicationId))db.update("UPDATE person SET status='已关闭',result='公司淘汰',company_intent='放弃',reason=?,updated_at=?,revision=revision+1 WHERE id=? AND org_id=?",reason,timestamp,personId,user.org());}
    private void syncCommunicationToApplication(long personId,Long applicationId,Map<String,Object> communication){if(applicationId==null)return;String timestamp=now(),result=str(communication,"result"),status="候选人拒绝".equals(result)?"候选人退出":"公司淘汰".equals(result)?"公司淘汰":null;db.update("UPDATE application SET company_intent=?,talent_intent=?,next_step=?,next_contact_at=?,status=COALESCE(?,status),reason=COALESCE(?,reason),updated_at=?,revision=revision+1 WHERE id=? AND person_id=? AND org_id=?",communication.get("companyIntent"),communication.get("talentIntent"),communication.get("nextStep"),communication.get("nextContactAt"),status,communication.get("reason"),timestamp,applicationId,personId,user.org());Long newest=db.queryForObject("SELECT MAX(id) FROM application WHERE org_id=? AND person_id=?",Long.class,user.org(),personId);if(Objects.equals(newest,applicationId))db.update("UPDATE person SET company_intent=?,talent_intent=?,next_step=?,next_contact_at=?,status=COALESCE(?,status),reason=COALESCE(?,reason),updated_at=?,revision=revision+1 WHERE id=? AND org_id=?",communication.get("companyIntent"),communication.get("talentIntent"),communication.get("nextStep"),communication.get("nextContactAt"),status,communication.get("reason"),timestamp,personId,user.org());}
    private void ensureEmployment(long personId,long applicationId,Map<String,Object> application,Map<String,Object> onboarding){
        Long onboardingId=db.query("SELECT id FROM onboarding WHERE org_id=? AND person_id=? AND application_id=? ORDER BY id DESC LIMIT 1",(r,n)->r.getLong(1),user.org(),personId,applicationId).stream().findFirst().orElse(null);
        if(onboardingId==null)onboardingId=saveOnboarding(personId,applicationId,onboarding);
        Map<String,Object> saved=embeddedRecords(personId,"employments").stream().filter(item->Objects.equals(idOrNull(item.get("applicationId")),applicationId)).findFirst().orElse(null);
        if(saved==null){Map<String,Object> employment=new LinkedHashMap<>();employment.put("applicationId",applicationId);employment.put("jobId",application.get("jobId"));employment.put("startDate",onboarding.get("startDate"));employment.put("status","试用期");employment.put("owner",application.get("owner"));employment.put("remark","由入职登记表建立");saved=saveRecord(personId,"employments",null,employment);}
        Map<String,Object> employeeData=new LinkedHashMap<>(saved);employeeData.put("employeeName",onboarding.get("employeeName"));employeeData.put("startDate",onboarding.get("startDate"));schema.syncEmployeeFromEmployment(user.org(),personId,id(saved.get("id")),employeeData);
        db.update("UPDATE employee SET onboarding_id=? WHERE org_id=? AND person_id=? AND application_id=?",onboardingId,user.org(),personId,applicationId);
    }
    private long saveOnboarding(long personId,long applicationId,Map<String,Object> onboarding){String timestamp=now(),columns=StructuredColumns.ONBOARDING.values().stream().map(StructuredColumns::column).collect(Collectors.joining(","));String marks=String.join(",",Collections.nCopies(StructuredColumns.ONBOARDING.size()+6,"?"));List<Object> values=new ArrayList<>(List.of(user.org(),personId,applicationId,1,timestamp,timestamp));values.addAll(structuredValues(StructuredColumns.ONBOARDING,onboarding));GeneratedKeyHolder keys=new GeneratedKeyHolder();db.update(c->{PreparedStatement p=c.prepareStatement("INSERT INTO onboarding(org_id,person_id,application_id,revision,created_at,updated_at,"+columns+") VALUES("+marks+")",Statement.RETURN_GENERATED_KEYS);for(int i=0;i<values.size();i++)p.setObject(i+1,values.get(i));return p;},keys);long onboardingId=Objects.requireNonNull(keys.getKey()).longValue();Map<String,Object> event=event("onboarding","新增入职登记","已建立独立入职表","",Objects.toString(onboarding.get("onboardedAt"),timestamp));event.put("recordId",onboardingId);event.put("applicationId",applicationId);event.put("result","已登记");appendEvent(personId,event);return onboardingId;}
    private void recordEvent(long personId,String type,long recordId,Map<String,Object> before,Map<String,Object> body){String singular=type.equals("opportunities")?"opportunity":type.equals("experiences")?"experience":type.substring(0,type.length()-1);Map<String,Object> event=event(singular,(before.isEmpty()?"新增":"更新")+LABELS.getOrDefault(type,type),summary(type,body),str(body,"reason"),now());event.put("result",str(body,"result").isBlank()?str(body,"status"):body.get("result"));for(String key:List.of("applicationId","jobId","nextStep","nextContactAt","owner"))if(body.get(key)!=null)event.put(key,body.get(key));if(before.isEmpty())for(String key:List.of("occurredAt","startedAt","startDate","scheduledAt"))if(!str(body,key).isBlank()){event.put("occurredAt",body.get(key));break;}event.put("recordId",recordId);appendEvent(personId,event);}
    private Map<String,Object> event(String type,String title,String summary,String reason,String occurredAt){Map<String,Object> e=new LinkedHashMap<>();e.put("type",type);e.put("title",title);e.put("summary",summary);e.put("reason",reason);e.put("occurredAt",occurredAt);return e;}
    private String summary(String type,Map<String,Object> body){List<String> parts=new ArrayList<>();for(String key:List.of("title","jobName","projectName","organization","name","round","status","feedback","remark")){String value=str(body,key);if(!value.isBlank())parts.add(value);}if(type.equals("offers"))parts.add("第 "+body.get("version")+" 版 · "+body.get("salaryMin")+"–"+body.get("salaryMax")+"K/月");return String.join(" · ",parts);}
    private void appendEvent(long personId,Map<String,Object> event){String created=now(),occurred=str(event,"occurredAt").isBlank()?created:str(event,"occurredAt"),entityType=str(event,"type").isBlank()?"person":str(event,"type"),action=str(event,"action").isBlank()?(str(event,"title").startsWith("更新")?"updated":str(event,"title").startsWith("删除")?"deleted":"created"):str(event,"action");db.update("INSERT INTO record(org_id,person_id,application_id,entity_type,entity_id,action,title,summary,result,reason,occurred_at,actor,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)",user.org(),personId,idOrNull(event.get("applicationId")),entityType,idOrNull(event.get("recordId")),action,event.get("title"),event.get("summary"),event.get("result"),event.get("reason"),occurred,user.name(),created);}

    public Map<String,Object> workspace(){Map<String,Object> result=new LinkedHashMap<>();for(String type:TYPES)result.put(type,recordsAcross(type));List<Map<String,Object>> positionList=positions();Map<Long,Map<String,Object>> positionById=positionList.stream().collect(Collectors.toMap(item->idOrNull(item.get("id")),item->item,(a,b)->a));for(String type:TYPES){Object value=result.get(type);if(!(value instanceof List<?> list))continue;for(Object entry:list){if(!(entry instanceof Map<?,?> raw))continue;Map<String,Object> item=(Map<String,Object>)raw;Map<String,Object> job=positionById.get(idOrNull(item.get("jobId")));if(job!=null)copyPositionCapacity(job,item);}}List<Map<String,Object>> employmentRows=(List<Map<String,Object>>)result.get("employments");Map<Long,Map<String,Object>> employeeByOnboarding=employees().stream().filter(item->idOrNull(item.get("onboardingId"))!=null).collect(Collectors.toMap(item->idOrNull(item.get("onboardingId")),item->item,(a,b)->a));for(Map<String,Object> employment:employmentRows){Map<String,Object> employee=employeeByOnboarding.get(idOrNull(employment.get("onboardingId")));if(employee!=null){employment.put("employeeId",employee.get("id"));employment.put("employeeNumber",employee.get("employeeNumber"));employment.put("employeeRole",employee.get("role"));employment.put("username",employee.get("username"));employment.put("hasAccount",employee.get("hasAccount"));employment.put("currentEmployee",employee.get("current"));}}List<Map<String,Object>> employeeRows=employees().stream().map(item->{Map<String,Object> value=new LinkedHashMap<>(item);value.put("personName",item.get("name"));value.put("jobName",str(item,"title").isBlank()?"员工":item.get("title"));value.put("employeeRole",item.get("role"));value.put("currentEmployee",item.get("current"));employmentRows.stream().filter(employment->Objects.equals(idOrNull(employment.get("personId")),idOrNull(item.get("personId")))&&Objects.equals(idOrNull(employment.get("applicationId")),idOrNull(item.get("applicationId")))).findFirst().ifPresent(employment->value.put("employmentItemId",employment.get("id")));return value;}).toList();result.put("employees",employeeRows);List<Map<String,Object>> people=persons();result.put("stats",list("","","",null,1,10).get("stats"));result.put("sources",group(people,"source"));result.put("stages",group(people,"status"));result.put("outcomes",group(people,"result"));result.put("jobs",group(people,"job"));return result;}
    private Map<String,Long> group(List<Map<String,Object>> people,String key){return people.stream().collect(Collectors.groupingBy(p->str(p,key).isBlank()?"未填写":str(p,key),LinkedHashMap::new,Collectors.counting()));}
    private List<Map<String,Object>> recordsAcross(String type){List<Map<String,Object>> rows;if(type.equals("applications"))rows=applicationRows("SELECT a.*,e.name owner_name,p.name person_name FROM application a LEFT JOIN employee e ON e.id=a.owner_employee_id AND e.org_id=a.org_id JOIN person p ON p.id=a.person_id AND p.org_id=a.org_id WHERE a.org_id=? ORDER BY a.id DESC",user.org());else if(type.equals("events"))rows=ledgerRows("SELECT r.*,p.name person_name FROM record r JOIN person p ON p.id=r.person_id AND p.org_id=r.org_id WHERE r.org_id=? ORDER BY r.id DESC",user.org());else if(PERSON_RECORD_TYPES.contains(type)){rows=new ArrayList<>();for(Map<String,Object> person:persons()){for(Map<String,Object> item:embeddedRecords(id(person.get("id")),type)){item.put("personName",person.get("name"));rows.add(item);}}}else{String table=businessTable(type);rows=recordRows("SELECT r.*,e.name owner_name,p.name person_name FROM "+table+" r LEFT JOIN employee e ON e.id=r.owner_employee_id AND e.org_id=r.org_id JOIN person p ON p.id=r.person_id AND p.org_id=r.org_id WHERE r.org_id=? ORDER BY r.id DESC",user.org());}if(type.equals("employments"))attachOnboarding(rows);if(type.equals("offers"))attachOfferResponses(rows);return rows;}

    public Map<String,Object> publicOffer(String token){return publicOfferRow(token,false);}
    @Transactional public Map<String,Object> respondToOffer(String token,Map<String,Object> input){
        Map<String,Object> offer=publicOfferRow(token,true);String decision=Objects.toString(input.get("decision"),"").strip().toUpperCase(Locale.ROOT),status=switch(decision){case "ACCEPTED","接受","已接受"->"已接受";case "DECLINED","拒绝","已拒绝"->"已拒绝";default->throw ApiException.bad("请选择接受或拒绝 Offer");};String reason=Objects.toString(input.get("reason"),"").strip();if("已拒绝".equals(status)&&reason.isBlank())throw ApiException.bad("拒绝 Offer 时请填写原因");String current=Objects.toString(offer.get("responseStatus"),"待回复");if(Set.of("已接受","已拒绝").contains(current)){if(current.equals(status))return offer;throw new ApiException(409,"OFFER_ALREADY_RESPONDED","这份 Offer 已经提交过回复，不能重复更改");}
        LocalDate expires=LocalDate.parse(Objects.toString(offer.get("expiresAt")));if(expires.isBefore(LocalDate.now(ZoneId.of("Asia/Shanghai"))))throw new ApiException(410,"OFFER_EXPIRED","这份 Offer 已过有效期，请联系 HR");
        long offerId=((Number)offer.get("id")).longValue(),org=((Number)offer.get("orgId")).longValue(),personId=((Number)offer.get("personId")).longValue(),applicationId=((Number)offer.get("applicationId")).longValue(),ownerId=((Number)offer.get("ownerEmployeeId")).longValue();String timestamp=now();
        db.update("UPDATE offer SET response_status=?,responded_at=?,response_reason=? WHERE id=? AND org_id=?",status,timestamp,reason.isBlank()?null:reason,offerId,org);
        if("已接受".equals(status)){db.update("UPDATE application SET status='待入职',talent_intent='强烈',updated_at=?,revision=revision+1 WHERE id=? AND org_id=? AND person_id=?",timestamp,applicationId,org,personId);db.update("UPDATE person SET status='待入职',talent_intent='强烈',updated_at=?,revision=revision+1 WHERE id=? AND org_id=?",timestamp,personId,org);}else{String closeReason="候选人拒绝 Offer："+reason;db.update("UPDATE application SET status='候选人退出',talent_intent='明确拒绝',reason=?,updated_at=?,revision=revision+1 WHERE id=? AND org_id=? AND person_id=?",closeReason,timestamp,applicationId,org,personId);db.update("UPDATE person SET status='已关闭',result='候选人退出',talent_intent='明确拒绝',reason=?,updated_at=?,revision=revision+1 WHERE id=? AND org_id=?",closeReason,timestamp,personId,org);}
        String personName=Objects.toString(offer.get("personName"),"候选人"),jobName=Objects.toString(offer.get("jobName"),"岗位");createMessage(org,ownerId,"Offer 回复",personName+"已"+("已接受".equals(status)?"接受":"拒绝")+" Offer",jobName+(reason.isBlank()?"":" · "+reason),status,null,null,"offer-response-"+offerId);db.update("INSERT INTO record(org_id,person_id,application_id,entity_type,entity_id,action,title,summary,result,reason,occurred_at,actor,created_at) VALUES(?,?,?,'offer',?,'responded','候选人回复 Offer',?,?,?,?,?,'候选人',?)",org,personId,applicationId,offerId,personName+"已"+("已接受".equals(status)?"接受":"拒绝")+" "+jobName,status,reason,timestamp,timestamp);db.update("INSERT INTO audit(org_id,actor,action,created_at,person_id,record_id,summary) VALUES(?,'候选人','offer.respond',?,?,?,'候选人通过邮件页面回复 Offer')",org,timestamp,personId,offerId);
        return publicOfferRow(token,false);
    }
    private Map<String,Object> publicOfferRow(String token,boolean lock){String hash=tokenHash(token);List<Map<String,Object>> rows=db.queryForList("SELECT o.id,o.org_id,o.person_id,o.application_id,o.owner_employee_id,o.job_name,o.company,o.salary_mode,o.actual_salary,o.annual_salary,o.salary_months,o.probation_months,o.social_insurance,o.expected_start_date,o.expires_at,o.sent_at,o.response_status,o.responded_at,o.response_reason,p.name person_name,e.name owner_name FROM offer o JOIN person p ON p.id=o.person_id AND p.org_id=o.org_id LEFT JOIN employee e ON e.id=o.owner_employee_id AND e.org_id=o.org_id WHERE o.response_token_hash=? AND o.current_record=TRUE AND o.status='已完成'"+(lock?" FOR UPDATE":""),hash);if(rows.isEmpty())throw new ApiException(404,"OFFER_LINK_INVALID","Offer 链接不存在或已经失效");Map<String,Object> row=rows.get(0),out=new LinkedHashMap<>();out.put("id",row.get("id"));out.put("orgId",row.get("org_id"));out.put("personId",row.get("person_id"));out.put("applicationId",row.get("application_id"));out.put("ownerEmployeeId",row.get("owner_employee_id"));out.put("personName",row.get("person_name"));out.put("jobName",row.get("job_name"));out.put("company",row.get("company"));out.put("salaryMode",row.get("salary_mode"));out.put("actualSalary",row.get("actual_salary"));out.put("annualSalary",row.get("annual_salary"));out.put("salaryMonths",row.get("salary_months"));out.put("probationMonths",row.get("probation_months"));out.put("socialInsurance",row.get("social_insurance"));out.put("expectedStartDate",row.get("expected_start_date"));out.put("expiresAt",row.get("expires_at"));out.put("sentAt",row.get("sent_at"));out.put("responseStatus",Objects.toString(row.get("response_status"),"待回复"));out.put("respondedAt",row.get("responded_at"));out.put("responseReason",row.get("response_reason"));out.put("owner",row.get("owner_name"));out.put("expired",LocalDate.parse(Objects.toString(row.get("expires_at"))).isBefore(LocalDate.now(ZoneId.of("Asia/Shanghai"))));return out;}
    private String newOfferToken(){return newSecureToken();}
    private String newSecureToken(){byte[] bytes=new byte[32];new SecureRandom().nextBytes(bytes);return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);}
    private String tokenHash(String token){try{return secureTokenHash(token);}catch(ApiException e){throw new ApiException(404,"OFFER_LINK_INVALID","Offer 链接不存在或已经失效");}}
    private String secureTokenHash(String token){if(token==null||!token.matches("^[A-Za-z0-9_-]{40,100}$"))throw new ApiException(404,"LINK_INVALID","专属链接不存在或已经失效");try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(token.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException("无法校验专属链接",e);}}

    public Map<String,Object> inbox(){
        Long employeeId=currentEmployeeId();if(employeeId==null)return Map.of("items",List.of(),"count",0,"unreadCount",0);
        List<Map<String,Object>> items=db.query("SELECT m.id,m.category,m.title,m.summary,m.status,m.person_id,m.interview_id,m.is_read,m.read_at,m.created_at,i.person_id interview_person_id FROM message m LEFT JOIN interview i ON i.id=m.interview_id AND i.org_id=m.org_id WHERE m.org_id=? AND m.recipient_employee_id=? ORDER BY m.created_at DESC,m.id DESC",(r,n)->{Map<String,Object> item=new LinkedHashMap<>();item.put("id",r.getLong("id"));item.put("category",r.getString("category"));item.put("title",r.getString("title"));item.put("summary",r.getString("summary"));item.put("status",r.getString("status"));item.put("personId",r.getObject("person_id"));item.put("interviewId",r.getObject("interview_id"));item.put("read",r.getBoolean("is_read"));item.put("readAt",r.getString("read_at"));item.put("createdAt",r.getString("created_at"));Object directPerson=r.getObject("person_id"),interviewPerson=r.getObject("interview_person_id");item.put("route",directPerson!=null?"/person/"+directPerson:interviewPerson!=null?"/person/"+interviewPerson+"?tab=interviews":"/inbox");return item;},user.org(),employeeId);
        long unreadCount=items.stream().filter(item->!Boolean.TRUE.equals(item.get("read"))).count();return Map.of("items",items,"count",items.size(),"unreadCount",unreadCount);
    }
    @Transactional public Map<String,Object> markInboxRead(String messageId){
        Long id=id(messageId);Long employeeId=currentEmployeeId();if(id==null||employeeId==null)throw ApiException.bad("消息编号不正确");if(db.update("UPDATE message SET is_read=TRUE,read_at=COALESCE(read_at,?) WHERE id=? AND org_id=? AND recipient_employee_id=?",now(),id,user.org(),employeeId)==0)throw ApiException.missing();
        return Map.of("messageId",messageId,"read",true);
    }
    @Transactional public Map<String,Object> markAllInboxRead(){
        Long employeeId=currentEmployeeId();int changed=employeeId==null?0:db.update("UPDATE message SET is_read=TRUE,read_at=COALESCE(read_at,?) WHERE org_id=? AND recipient_employee_id=? AND is_read=FALSE",now(),user.org(),employeeId);
        return Map.of("read",true,"changed",changed,"unreadCount",0);
    }
    private Long currentEmployeeId(){return db.query("SELECT employee_id FROM user WHERE id=? AND org_id=? AND employee_id IS NOT NULL",(r,n)->r.getLong(1),user.id(),user.org()).stream().findFirst().orElse(null);}
    private void createMessage(long recipientEmployeeId,String category,String title,String summary,String status,Long personId,Long interviewId,String sourceKey){createMessage(user.org(),recipientEmployeeId,category,title,summary,status,personId,interviewId,sourceKey);}
    private void createMessage(long org,long recipientEmployeeId,String category,String title,String summary,String status,Long personId,Long interviewId,String sourceKey){if(personId!=null&&interviewId!=null)throw new IllegalArgumentException("消息只能关联人才或面试中的一种");Integer exists=db.queryForObject("SELECT COUNT(*) FROM message WHERE org_id=? AND recipient_employee_id=? AND source_key=?",Integer.class,org,recipientEmployeeId,sourceKey);if(exists!=null&&exists>0)return;db.update("INSERT INTO message(org_id,recipient_employee_id,category,title,summary,status,person_id,interview_id,source_key,is_read,created_at) VALUES(?,?,?,?,?,?,?,?,?,FALSE,?)",org,recipientEmployeeId,category,title,summary,status,personId,interviewId,sourceKey,now());}

    public List<Map<String,Object>> auditLog(){List<Map<String,Object>> audits=db.query("SELECT id,actor,action,created_at,person_id,record_id,position_id,summary FROM audit WHERE org_id=? ORDER BY id DESC LIMIT 200",(r,n)->{Map<String,Object> a=new LinkedHashMap<>();a.put("id",r.getLong("id"));a.put("actor",r.getString("actor"));a.put("action",r.getString("action"));a.put("createdAt",r.getString("created_at"));a.put("personId",r.getObject("person_id"));a.put("recordId",r.getObject("record_id"));a.put("positionId",r.getObject("position_id"));a.put("summary",r.getString("summary"));return a;},user.org());for(Map<String,Object> audit:audits)audit.put("details",db.query("SELECT field_name,before_value,after_value FROM audit_change WHERE audit_id=? ORDER BY id",(r,n)->Map.of("field",r.getString(1),"before",Objects.toString(r.getString(2),""),"after",Objects.toString(r.getString(3),"")),audit.get("id")));return audits;}
    private void audit(String action,Map<String,Object> data){audits.recordBusinessChange(user.org(),user.name(),action,data);}

    private List<Map<String,Object>> personRows(String sql,Object...args){return db.query(sql,(r,n)->{Map<String,Object> p=new LinkedHashMap<>();p.put("id",r.getLong("id"));p.put("version",r.getLong("revision"));for(Map.Entry<String,String> e:PERSON_COLUMNS.entrySet()){Object value=Set.of("salaryMin","salaryMax").contains(e.getKey())?r.getBigDecimal(e.getValue()):r.getObject(e.getValue());if(e.getKey().equals("tags")&&value!=null)value=Arrays.stream(value.toString().split("[，,]")).filter(s->!s.isBlank()).toList();if(PERSON_RECORD_TYPES.contains(e.getKey()))value=readEmbedded(value);p.put(e.getKey(),value);}long owner=r.getLong("owner_employee_id");Long ownerId=r.wasNull()?null:owner;p.put("ownerEmployeeId",ownerId);p.put("ownerHrId",ownerId);p.put("owner",r.getString("owner_name"));if(p.get("salaryMin")!=null)p.put("salary",p.get("salaryMin")+"–"+p.get("salaryMax")+"K/月");else p.put("salary","");return p;},args);}
    private List<Map<String,Object>> positionRows(String sql,Object...args){return db.query(sql,(r,n)->{Map<String,Object> p=new LinkedHashMap<>();p.put("id",r.getLong("id"));p.put("version",r.getLong("version_number"));for(Map.Entry<String,String> e:StructuredColumns.POSITION.entrySet())p.put(e.getKey(),r.getObject(StructuredColumns.column(e.getValue())));p.put("owner",r.getString("owner_name"));return p;},args);}
    private List<Map<String,Object>> attachPositionCapacity(List<Map<String,Object>> rows){
        if(rows.isEmpty())return rows;
        String today=LocalDate.now(ZoneId.of("Asia/Shanghai")).toString();
        List<Map<String,Object>> counts=db.queryForList("SELECT job_id,COUNT(DISTINCT application_id) occupied_count,COUNT(DISTINCT CASE WHEN hired=1 THEN application_id END) hired_count FROM (SELECT job_id,id application_id,CASE WHEN status='已入职' THEN 1 ELSE 0 END hired FROM application WHERE org_id=? AND status IN ('待入职','已入职') UNION ALL SELECT job_id,application_id,0 hired FROM offer WHERE org_id=? AND current_record=TRUE AND status='已完成' AND COALESCE(response_status,'待回复')<>'已拒绝' AND (response_status='已接受' OR expires_at>=?)) capacity GROUP BY job_id",user.org(),user.org(),today);
        Map<Long,Map<String,Object>> byJob=counts.stream().filter(item->idOrNull(item.get("job_id"))!=null).collect(Collectors.toMap(item->idOrNull(item.get("job_id")),item->item,(a,b)->a));
        for(Map<String,Object> row:rows){int headcount=positiveInt(row.get("headcount"),1);Map<String,Object> count=byJob.get(idOrNull(row.get("id")));int occupied=count==null?0:positiveInt(count.get("occupied_count"),0),hired=count==null?0:positiveInt(count.get("hired_count"),0);row.put("headcount",headcount);row.put("occupiedCount",occupied);row.put("hiredCount",hired);row.put("remainingCount",Math.max(0,headcount-occupied));row.put("capacityReached",occupied>=headcount);}
        return rows;
    }
    private int positiveInt(Object value,int fallback){if(value==null)return fallback;try{return Math.max(0,new BigDecimal(value.toString()).intValue());}catch(Exception ignored){return fallback;}}
    private void copyPositionCapacity(Map<String,Object> job,Map<String,Object> target){for(String key:List.of("headcount","occupiedCount","hiredCount","remainingCount","capacityReached"))target.put(key,job.get(key));}
    private void ensureOfferCapacity(long jobId,long applicationId){
        db.queryForObject("SELECT id FROM position WHERE id=? AND org_id=? AND parent_position_id IS NULL AND COALESCE(current_record,TRUE)=TRUE FOR UPDATE",Long.class,jobId,user.org());
        Map<String,Object> job=position(jobId);int headcount=positiveInt(job.get("headcount"),1);
        Integer occupied=db.queryForObject("SELECT COUNT(DISTINCT application_id) FROM (SELECT id application_id FROM application WHERE org_id=? AND job_id=? AND id<>? AND status IN ('待入职','已入职') UNION ALL SELECT application_id FROM offer WHERE org_id=? AND job_id=? AND application_id<>? AND current_record=TRUE AND status='已完成' AND COALESCE(response_status,'待回复')<>'已拒绝' AND (response_status='已接受' OR expires_at>=?)) capacity",Integer.class,user.org(),jobId,applicationId,user.org(),jobId,applicationId,LocalDate.now(ZoneId.of("Asia/Shanghai")).toString());
        if(occupied!=null&&occupied>=headcount)throw ApiException.bad("岗位名额已满（"+headcount+" 人），不能再创建或发送 Offer");
    }
    private List<Map<String,Object>> recordRows(String sql,Object...args){List<Map<String,Object>> rows=db.query(sql,(r,n)->{Map<String,Object> b=new LinkedHashMap<>();b.put("id",r.getLong("id"));b.put("revision",r.getLong("revision"));b.put("personId",r.getLong("person_id"));b.put("personName",r.getString("person_name"));for(Map.Entry<String,String> e:StructuredColumns.RECORD.entrySet()){Object value=r.getObject(StructuredColumns.column(e.getValue()));if(value!=null)b.put(e.getKey(),value);}b.put("owner",r.getString("owner_name"));return b;},args);for(Map<String,Object> row:rows){Long jobId=idOrNull(row.get("jobId"));if(jobId!=null&&str(row,"company").isBlank()){try{Map<String,Object> job=position(jobId);row.put("company",job.get("company"));row.put("jobCode",str(job,"recruitmentCode").isBlank()?String.format("%03d",jobId):job.get("recruitmentCode"));row.put("baseLocation",job.get("baseLocation"));}catch(ApiException ignored){}}}return rows;}
    private List<Map<String,Object>> applicationRows(String sql,Object...args){return recordRows(sql,args);}
    private List<Map<String,Object>> ledgerRows(String sql,Object...args){return db.query(sql,(r,n)->{Map<String,Object> item=new LinkedHashMap<>();item.put("id",r.getLong("id"));item.put("personId",r.getLong("person_id"));item.put("personName",r.getString("person_name"));item.put("applicationId",r.getObject("application_id"));item.put("recordType",r.getString("entity_type"));item.put("type",r.getString("entity_type"));item.put("recordId",r.getObject("entity_id"));item.put("action",r.getString("action"));item.put("title",r.getString("title"));item.put("summary",r.getString("summary"));item.put("result",r.getString("result"));item.put("reason",r.getString("reason"));item.put("occurredAt",r.getString("occurred_at"));item.put("actor",r.getString("actor"));item.put("createdAt",r.getString("created_at"));return item;},args);}
    private List<Map<String,Object>> readEmbedded(Object value){if(value==null||value.toString().isBlank())return new ArrayList<>();try{return new ArrayList<>(json.readList(value.toString()));}catch(Exception ignored){return new ArrayList<>();}}
    private List<Map<String,Object>> embeddedRecords(long personId,String type){String value=db.queryForObject("SELECT "+type+" FROM person WHERE id=? AND org_id=?",String.class,personId,user.org());List<Map<String,Object>> rows=readEmbedded(value);for(Map<String,Object> row:rows){row.putIfAbsent("personId",personId);row.putIfAbsent("revision",1);}return rows;}
    private long insertEmbeddedRecord(long personId,String type,Map<String,Object> body){db.queryForObject("SELECT id FROM person WHERE id=? AND org_id=? FOR UPDATE",Long.class,personId,user.org());List<Map<String,Object>> rows=embeddedRecords(personId,type);long next=rows.stream().map(item->idOrNull(item.get("id"))).filter(Objects::nonNull).mapToLong(Long::longValue).max().orElse(0)+1;body.put("id",next);rows.add(json.copy(body));writeEmbedded(personId,type,rows);return next;}
    private int updateEmbeddedRecord(long personId,String type,long recordId,long expected,Map<String,Object> body){db.queryForObject("SELECT id FROM person WHERE id=? AND org_id=? FOR UPDATE",Long.class,personId,user.org());List<Map<String,Object>> rows=embeddedRecords(personId,type);for(int index=0;index<rows.size();index++){Map<String,Object> current=rows.get(index);if(Objects.equals(idOrNull(current.get("id")),recordId)&&Objects.equals(idOrNull(current.get("revision")),expected)){body.put("id",recordId);rows.set(index,json.copy(body));writeEmbedded(personId,type,rows);return 1;}}return 0;}
    private void writeEmbedded(long personId,String type,List<Map<String,Object>> rows){if(!PERSON_RECORD_TYPES.contains(type))throw ApiException.bad("不支持的人才档案属性");db.update("UPDATE person SET "+type+"=?,updated_at=?,revision=revision+1 WHERE id=? AND org_id=?",json.write(rows),now(),personId,user.org());}
    private String businessTable(String type){return switch(type){case "communications"->"communication";case "interviews"->"interview";case "offers"->"offer";default->throw ApiException.bad("该资料已经并入人才主档案");};}
    private void attachOnboarding(List<Map<String,Object>> employments){for(Map<String,Object> employment:employments){Long applicationId=idOrNull(employment.get("applicationId"));if(applicationId==null)continue;List<Map<String,Object>> rows=db.queryForList("SELECT * FROM onboarding WHERE org_id=? AND person_id=? AND application_id=? ORDER BY id DESC LIMIT 1",user.org(),employment.get("personId"),applicationId);if(rows.isEmpty())continue;Map<String,Object> row=rows.get(0);employment.put("onboardingId",row.get("id"));for(Map.Entry<String,String> entry:StructuredColumns.ONBOARDING.entrySet()){Object value=row.get(StructuredColumns.column(entry.getValue()));if(value!=null)employment.put(entry.getKey(),value);}}}
    private void attachOfferResponses(List<Map<String,Object>> offers){for(Map<String,Object> offer:offers){List<Map<String,Object>> rows=db.queryForList("SELECT response_token_hash,response_status,responded_at,response_reason FROM offer WHERE id=? AND org_id=?",offer.get("id"),user.org());if(rows.isEmpty())continue;Map<String,Object> row=rows.get(0);for(Map.Entry<String,String> entry:StructuredColumns.OFFER_RESPONSE.entrySet()){Object value=row.get(StructuredColumns.column(entry.getValue()));if(value!=null)offer.put(entry.getKey(),value);}}}

    private int updatePosition(long id,long expected,long ownerId,Map<String,Object> body){String set=StructuredColumns.POSITION.values().stream().map(v->StructuredColumns.column(v)+"=?").collect(Collectors.joining(","));List<Object> values=structuredValues(StructuredColumns.POSITION,body);values.add(ownerId);values.add(body.get("version"));values.add(id);values.add(user.org());values.add(expected);return db.update("UPDATE position SET "+set+",owner_employee_id=?,version_number=?,revision=revision+1 WHERE id=? AND org_id=? AND revision=? AND parent_position_id IS NULL",values.toArray());}
    private void archivePositionVersion(long positionId,long ownerId,Map<String,Object> body){String columns=StructuredColumns.POSITION.values().stream().map(StructuredColumns::column).collect(Collectors.joining(","));String marks=String.join(",",Collections.nCopies(StructuredColumns.POSITION.size()+6,"?"));List<Object> values=new ArrayList<>(List.of(user.org(),1,positionId,false,body.get("version"),ownerId));values.addAll(structuredValues(StructuredColumns.POSITION,body));db.update("INSERT INTO `position`(org_id,revision,parent_position_id,current_record,version_number,owner_employee_id,"+columns+") VALUES("+marks+")",values.toArray());}
    private long insertRecord(long personId,String type,long ownerId,Map<String,Object> body){String table=businessTable(type);boolean offerTable=table.equals("offer");String columns=(offerTable?"version,":"")+StructuredColumns.RECORD.values().stream().map(StructuredColumns::column).collect(Collectors.joining(","));String marks=String.join(",",Collections.nCopies(StructuredColumns.RECORD.size()+4+(offerTable?1:0),"?"));List<Object> values=new ArrayList<>(List.of(user.org(),personId,1,ownerId));if(offerTable)values.add(body.get("version"));values.addAll(structuredValues(StructuredColumns.RECORD,body));GeneratedKeyHolder keys=new GeneratedKeyHolder();db.update(c->{PreparedStatement p=c.prepareStatement("INSERT INTO "+table+"(org_id,person_id,revision,owner_employee_id,"+columns+") VALUES("+marks+")",Statement.RETURN_GENERATED_KEYS);for(int i=0;i<values.size();i++)p.setObject(i+1,values.get(i));return p;},keys);return Objects.requireNonNull(keys.getKey()).longValue();}
    private long insertApplication(long personId,long ownerId,Map<String,Object> body){return insertApplication(user.org(),personId,ownerId,body);}
    private long insertApplication(long orgId,long personId,long ownerId,Map<String,Object> body){String columns=StructuredColumns.RECORD.values().stream().map(StructuredColumns::column).collect(Collectors.joining(","));String marks=String.join(",",Collections.nCopies(StructuredColumns.RECORD.size()+4,"?"));List<Object> values=new ArrayList<>(List.of(orgId,personId,1,ownerId));values.addAll(structuredValues(StructuredColumns.RECORD,body));GeneratedKeyHolder keys=new GeneratedKeyHolder();db.update(connection->{PreparedStatement statement=connection.prepareStatement("INSERT INTO application(org_id,person_id,revision,owner_employee_id,"+columns+") VALUES("+marks+")",Statement.RETURN_GENERATED_KEYS);for(int index=0;index<values.size();index++)statement.setObject(index+1,values.get(index));return statement;},keys);return Objects.requireNonNull(keys.getKey()).longValue();}
    private int updateApplication(long applicationId,long personId,long expected,long ownerId,Map<String,Object> body){String set=StructuredColumns.RECORD.values().stream().map(value->StructuredColumns.column(value)+"=?").collect(Collectors.joining(","));List<Object> values=structuredValues(StructuredColumns.RECORD,body);values.add(ownerId);values.add(applicationId);values.add(user.org());values.add(personId);values.add(expected);return db.update("UPDATE application SET "+set+",owner_employee_id=?,revision=revision+1 WHERE id=? AND org_id=? AND person_id=? AND revision=?",values.toArray());}
    private int updateRecord(long recordId,long personId,String type,long expected,long ownerId,Map<String,Object> body){String table=businessTable(type),set=StructuredColumns.RECORD.values().stream().map(v->StructuredColumns.column(v)+"=?").collect(Collectors.joining(","));List<Object> values=structuredValues(StructuredColumns.RECORD,body);values.add(ownerId);values.add(recordId);values.add(user.org());values.add(personId);values.add(expected);return db.update("UPDATE "+table+" SET "+set+",owner_employee_id=?,revision=revision+1 WHERE id=? AND org_id=? AND person_id=? AND revision=?",values.toArray());}
    private List<Object> structuredValues(LinkedHashMap<String,String> columns,Map<String,Object> body){List<Object> out=new ArrayList<>();for(String key:columns.keySet())out.add(structuredValue(body.get(key),key));return out;}
    private Object structuredValue(Object value,String key){if(value==null||value.toString().isBlank())return null;if(Set.of("salaryMin","salaryMax","actualSalary","annualSalary","score","amount").contains(key))return new BigDecimal(value.toString());if(Set.of("companyId","jobId","jobVersion","applicationId","opportunityId","size","version","identityFrontAssetId","identityBackAssetId","graduationCertificateAssetId","degreeCertificateAssetId","educationVerificationAssetId","departureCertificateAssetId").contains(key))return Long.valueOf(value.toString());if(Set.of("salaryMonths","validityDays","probationMonths").contains(key))return Integer.valueOf(value.toString());if(Set.of("external","currentRecord").contains(key))return value instanceof Boolean b?b:Boolean.valueOf(value.toString());return plain(value);}

    @Transactional public Map<String,Object> addUploadedAsset(long personId,Map<String,Object> asset){
        basePerson(personId);
        boolean unique=Set.of("证件照","简历").contains(str(asset,"type"));List<Map<String,Object>> before=embeddedRecords(personId,"assets");List<String> replaced=unique?before.stream().filter(item->str(item,"type").equals(str(asset,"type"))).map(item->str(item,"storageName")).filter(name->!name.isBlank()).toList():List.of();
        Map<String,Object> saved=saveRecord(personId,"assets",null,asset);long recordId=id(saved.get("id")),previousRevision=id(saved.get("revision"));saved.put("downloadUrl","/candidate/"+personId+"/assets/"+recordId+"/download");saved.put("url",saved.get("downloadUrl"));saved.put("revision",previousRevision+1);updateEmbeddedRecord(personId,"assets",recordId,previousRevision,saved);
        if(unique){List<Map<String,Object>> current=embeddedRecords(personId,"assets");current.removeIf(item->!Objects.equals(idOrNull(item.get("id")),recordId)&&str(item,"type").equals(str(asset,"type")));writeEmbedded(personId,"assets",current);}Map<String,Object> result=json.copy(saved);result.remove("storageName");result.put("_replacedStorageNames",replaced);return result;
    }
    public Map<String,Object> downloadAsset(long personId,long assetId){basePerson(personId);Map<String,Object> asset=record(personId,"assets",assetId);if(str(asset,"storageName").isBlank())throw ApiException.bad("此记录为外部链接，请使用原始链接访问");audit("asset.download",Map.of("personId",personId,"recordId",assetId,"before",Map.of(),"after",Map.of("name",asset.get("name"))));return asset;}
    @Transactional public Map<String,Object> deleteAsset(long personId,long assetId){basePerson(personId);Map<String,Object> asset=record(personId,"assets",assetId);List<Map<String,Object>> assets=embeddedRecords(personId,"assets");if(!assets.removeIf(item->Objects.equals(idOrNull(item.get("id")),assetId)))throw ApiException.missing();writeEmbedded(personId,"assets",assets);Map<String,Object> event=event("asset","删除附件",str(asset,"type")+" · "+str(asset,"name"),"",now());event.put("recordId",assetId);appendEvent(personId,event);audit("asset.delete",Map.of("personId",personId,"recordId",assetId,"before",asset,"after",Map.of()));return asset;}

    private void validType(String type){if(!TYPES.contains(type))throw ApiException.bad("不支持的记录类型");}
    private Map<String,Object> select(Map<String,Object> body,Set<String> fields){Map<String,Object> result=new LinkedHashMap<>();body.forEach((k,v)->{if(fields.contains(k))result.put(k,v instanceof String?((String)v).strip():v);});return result;}
    private static String now(){return OffsetDateTime.now().toString();}private static String str(Map<String,Object> body,String key){return Objects.toString(body.get(key),"").strip();}private static boolean blank(String text){return text==null||text.isBlank();}
    private static Long id(Object value){if(value==null||value.toString().isBlank())return null;try{long n=Long.parseLong(value.toString());if(n<=0)throw new NumberFormatException();return n;}catch(NumberFormatException e){throw ApiException.bad("关联记录编号不正确");}}private static Long idOrNull(Object value){try{return id(value);}catch(Exception ignored){return null;}}
    private static long version(Map<String,Object> body,String field){Long value=id(body.get(field));if(value==null)throw new ApiException(409,"VERSION_REQUIRED","请刷新后重试，更新记录需要 "+field);return value;}
    private void required(Map<String,Object> body,String key,String message){if(str(body,key).isBlank())throw ApiException.bad(message);}private void limit(Map<String,Object> body,String key,int max){if(str(body,key).length()>max)throw ApiException.bad(key+" 内容过长");}private void enumValue(Map<String,Object> body,String key,Set<String> allowed){if(!str(body,key).isBlank()&&!allowed.contains(str(body,key)))throw ApiException.bad(key+" 选项不正确");}
    private void reason(Map<String,Object> body,Map<String,Object> before){boolean closed=(CLOSED.contains(str(body,"status"))&&!Objects.equals(body.get("status"),before.get("status")))||(CLOSED.contains(str(body,"result"))&&!Objects.equals(body.get("result"),before.get("result")));if(closed&&str(body,"reason").isBlank())throw ApiException.bad("结束、拒绝或未入职时必须填写原因，以便保留完整历史");}
    private void validateIntent(Map<String,Object> body){enumValue(body,"companyIntent",Set.of("未判断","未知","低","一般","较高","很高","放弃","有兴趣","积极"));enumValue(body,"talentIntent",Set.of("未知","未判断","明确拒绝","暂不考虑","可以了解","有兴趣","积极","强烈"));}
    private void salary(Map<String,Object> body,String min,String max){if(blank(str(body,min)))body.put(min,null);if(blank(str(body,max)))body.put(max,null);if((body.get(min)==null)!=(body.get(max)==null))throw ApiException.bad("薪资最小值和最大值需要同时填写");decimal(body,min,BigDecimal.ZERO,new BigDecimal("100000"));decimal(body,max,BigDecimal.ZERO,new BigDecimal("100000"));if(body.get(min)!=null&&new BigDecimal(body.get(min).toString()).compareTo(new BigDecimal(body.get(max).toString()))>0)throw ApiException.bad("最高薪资必须大于或等于最低薪资");}
    private void validateContact(Map<String,Object> body){String phone=str(body,"phone"),wechat=str(body,"wechat"),email=str(body,"email");if(phone.isBlank()&&wechat.isBlank()&&email.isBlank())throw ApiException.bad("请至少填写手机、微信或邮箱中的一种联系方式");if(!phone.isBlank()&&!phone.replaceAll("[\\s()\\-]","").matches("^(?:\\+?86)?1[3-9]\\d{9}$"))throw ApiException.bad("请输入正确的 11 位中国大陆手机号");if(!wechat.isBlank()&&!wechat.matches("^[A-Za-z][-_A-Za-z0-9]{5,19}$"))throw ApiException.bad("微信号需以字母开头，共 6 至 20 位，可含数字、减号和下划线");if(!email.isBlank()&&!email.matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$"))throw ApiException.bad("请输入正确的邮箱地址");}
    private void validateOnboarding(Map<String,Object> body){
        required(body,"employmentCategory","请选择用工类型");enumValue(body,"employmentCategory",Set.of("全职","兼职","外包"));
        if("全职".equals(str(body,"employmentCategory"))){required(body,"hireChannel","请选择校招或社招");enumValue(body,"hireChannel",Set.of("校招","社招"));if("社招".equals(str(body,"hireChannel"))){required(body,"preEmploymentStatus","请选择社招人才目前在职或离职");enumValue(body,"preEmploymentStatus",Set.of("在职","离职"));}else body.put("preEmploymentStatus",null);}else{body.put("hireChannel",null);body.put("preEmploymentStatus",null);}
        for(Map.Entry<String,String> item:Map.ofEntries(Map.entry("employeeName","请填写姓名"),Map.entry("employeePhone","请填写电话"),Map.entry("employeeEmail","请填写邮箱"),Map.entry("identityNumber","请填写身份证号"),Map.entry("startDate","请选择到岗日期"),Map.entry("bankName","请填写开户银行"),Map.entry("bankAccount","请填写银行卡号"),Map.entry("address","请填写现住址"),Map.entry("householdRegistration","请填写户籍地址"),Map.entry("emergencyContact","请填写紧急联系人"),Map.entry("emergencyPhone","请填写紧急联系电话"),Map.entry("onboardedAt","缺少入职登记时间"),Map.entry("identityFrontAssetId","请上传身份证正面"),Map.entry("identityBackAssetId","请上传身份证反面")).entrySet())required(body,item.getKey(),item.getValue());
        if(!str(body,"employeePhone").replaceAll("[\\s()\\-]","").matches("^(?:\\+?86)?1[3-9]\\d{9}$"))throw ApiException.bad("请输入正确的 11 位中国大陆手机号");
        if(!str(body,"emergencyPhone").replaceAll("[\\s()\\-]","").matches("^(?:\\+?86)?1[3-9]\\d{9}$"))throw ApiException.bad("请输入正确的紧急联系电话");
        if(!str(body,"employeeEmail").matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$"))throw ApiException.bad("请输入正确的邮箱地址");
        if(!str(body,"identityNumber").matches("^[1-9]\\d{5}(?:19|20)\\d{2}(?:0[1-9]|1[0-2])(?:0[1-9]|[12]\\d|3[01])\\d{3}[0-9Xx]$"))throw ApiException.bad("请输入正确的 18 位身份证号");
        if(!str(body,"bankAccount").replace(" ","").matches("^\\d{12,25}$"))throw ApiException.bad("银行卡号应为 12 至 25 位数字");
        if(parseDate(str(body,"startDate"),"startDate").isBefore(LocalDate.now(ZoneId.of("Asia/Shanghai")).atStartOfDay(ZoneId.of("Asia/Shanghai")).toInstant()))throw ApiException.bad("到岗日期不能早于今天");
        if("校招".equals(str(body,"hireChannel"))){required(body,"graduationCertificateAssetId","校招入职请上传毕业证");required(body,"degreeCertificateAssetId","校招入职请上传学位证");required(body,"educationVerificationAssetId","校招入职请上传教育部学籍在线验证报告");}
        if("社招".equals(str(body,"hireChannel"))&&"离职".equals(str(body,"preEmploymentStatus")))required(body,"departureCertificateAssetId","离职状态的社招入职请上传离职证明");
    }
    private void decimal(Map<String,Object> body,String key,BigDecimal min,BigDecimal max){if(blank(str(body,key))){body.put(key,null);return;}try{BigDecimal n=new BigDecimal(str(body,key));if(n.compareTo(min)<0||n.compareTo(max)>0||n.scale()>4)throw new NumberFormatException();body.put(key,n);}catch(NumberFormatException e){throw ApiException.bad(key+" 必须是合理范围内的非负数字");}}
    private void integerChoice(Map<String,Object> body,String key,int min,int max,String message){if(blank(str(body,key)))return;try{int n=Integer.parseInt(str(body,key));if(n<min||n>max)throw new NumberFormatException();body.put(key,n);}catch(NumberFormatException e){throw ApiException.bad(message);}}
    private void validateDates(Map<String,Object> body){for(String key:List.of("applyTime","occurredAt","startedAt","scheduledAt","expectedStartDate","expiresAt","startDate","endDate","dueAt","nextContactAt","birthday","onboardedAt")){String value=str(body,key);if(!value.isBlank())parseDate(value,key);}if(!str(body,"startDate").isBlank()&&!str(body,"endDate").isBlank()&&parseDate(str(body,"startDate"),"startDate").isAfter(parseDate(str(body,"endDate"),"endDate")))throw ApiException.bad("结束日期不能早于开始日期");}
    private Instant parseDate(String text,String key){try{if(text.length()==10)return LocalDate.parse(text).atStartOfDay(ZoneId.of("Asia/Shanghai")).toInstant();try{return OffsetDateTime.parse(text).toInstant();}catch(DateTimeParseException e){return LocalDateTime.parse(text.replace(' ','T')).atZone(ZoneId.of("Asia/Shanghai")).toInstant();}}catch(DateTimeParseException e){throw ApiException.bad(key+" 日期格式不正确");}}
    private Map<String,Object> map(Object value){if(value instanceof Map<?,?> m){Map<String,Object> out=new LinkedHashMap<>();m.forEach((k,v)->out.put(Objects.toString(k),v));return out;}return Map.of();}
    private String plain(Object value){if(value==null)return null;if(value instanceof Collection<?> c)return c.stream().map(Object::toString).collect(Collectors.joining("，"));if(value instanceof Map<?,?>)return json.write(value);return Objects.toString(value);}
